// Dependencies supplied by prm44xx_54xx.h and prm.h remain external.

pub const OMAP54XX_PRM_BASE: u32 = 0x4ae06000;

#[macro_export]
macro_rules! OMAP54XX_PRM_REGADDR {
    ($inst:expr, $reg:expr) => {
        OMAP2_L4_IO_ADDRESS(OMAP54XX_PRM_BASE + ($inst) + ($reg))
    };
}

